CREATE FUNCTION dg_native_bill_apply(kind_value text,target text,action_value text,input jsonb,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;body jsonb:=input-ARRAY['focusVersion','selectionVersion'];action_id_value text;created text;bill_value text;quote_value text;operation_value text;lines_value jsonb;amount_value bigint;totals jsonb;reason_value text;payload jsonb;revision_value bigint;
 r restaurants%ROWTYPE;p dining_parties%ROWTYPE;o restaurant_orders%ROWTYPE;b restaurant_bills%ROWTYPE;q restaurant_financial_quotes%ROWTYPE;fixed _dg_native_bill_quote_origins%ROWTYPE;config restaurant_payment_configs%ROWTYPE;parent restaurant_financial_operations%ROWTYPE;operation restaurant_financial_operations%ROWTYPE;
BEGIN
 IF action_value NOT IN('config','review','refund_review','confirm','withdraw') OR jsonb_typeof(input) IS DISTINCT FROM 'object' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 meta:=dg_native_bill_context(kind_value,target,session_value,token_value,csrf_value,focus_value,true,action_value IN('refund_review','confirm','withdraw'));PERFORM dg_native_order_input(meta,input);SELECT * INTO r FROM restaurants WHERE id=meta->>'restaurantId';
 IF action_value='config' THEN
  IF kind_value<>'restaurant' OR NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['version','providerId','enabled','scenario','confirmed']);
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(body->'enabled') IS DISTINCT FROM 'boolean' OR body->>'providerId' IS NULL OR body->>'providerId' NOT IN('mock-payments','external-payments') OR body->>'scenario' IS NULL OR body->>'scenario' NOT IN('normal','failed','response_lost','unresolved') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
  IF body->>'providerId'='external-payments' AND body->'enabled'='true'::jsonb THEN PERFORM dg_native_bill_error('PAYMENT_PROVIDER_UNAVAILABLE');END IF;
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id FOR UPDATE;IF dg_native_restaurant_integer(body->'version',0,9007199254740991)<>coalesce(config.version,0) THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_config','restaurant',r.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;revision_value:=coalesce(config.version,0)+1;PERFORM dg_native_dining_effect(action_id_value,'restaurant_payment_configs',r.id);
  IF config.restaurant_id IS NULL THEN INSERT INTO restaurant_payment_configs VALUES(r.id,body->>'providerId',CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,'mock-merchant:'||r.id,body->>'scenario',revision_value,created,created);
  ELSE UPDATE restaurant_payment_configs SET provider_id=body->>'providerId',enabled=CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,scenario=body->>'scenario',version=revision_value,updated_at=created WHERE restaurant_id=r.id;END IF;
  INSERT INTO _dg_native_bill_config_revisions VALUES(r.id,revision_value,action_id_value,body->>'providerId',CASE WHEN body->'enabled'='true'::jsonb THEN 1 ELSE 0 END,'mock-merchant:'||r.id,body->>'scenario',created);INSERT INTO _dg_native_bill_results VALUES(action_id_value,r.id,NULL,NULL,created);RETURN action_id_value;
 END IF;
 SELECT * INTO p FROM dining_parties WHERE id=meta->>'partyId';SELECT * INTO o FROM restaurant_orders WHERE id=meta->>'orderId' FOR UPDATE;SELECT * INTO b FROM restaurant_bills WHERE order_id=o.id FOR UPDATE;
 IF action_value='review' THEN
  IF kind_value<>'order' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['orderVersion','billVersion','_quoteId','_confirmationHash']);
  IF dg_native_restaurant_integer(body->'orderVersion',1,9007199254740991)<>o.version OR dg_native_restaurant_integer(body->'billVersion',0,9007199254740991)<>coalesce(b.version,0) THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  reason_value:=dg_native_bill_payment_reason(o.id,meta);IF reason_value IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_NOT_REVIEWABLE');END IF;
  IF b.id IS NOT NULL THEN totals:=dg_native_bill_totals(b.id);IF(totals->>'paid')::bigint>0 OR(totals->>'activePayments')::bigint>0 OR(totals->>'activeRefunds')::bigint>0 OR b.attention_reason IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_PENDING');END IF;END IF;
  lines_value:=dg_native_bill_lines(o.id);SELECT coalesce(sum((value->>'subtotalMinor')::bigint),0) INTO amount_value FROM jsonb_array_elements(lines_value);IF amount_value NOT BETWEEN 0 AND 100000000 THEN PERFORM dg_native_bill_error('BILL_AMOUNT_INVALID');END IF;
  IF lines_value='[]'::jsonb AND o.status<>'cancelled' THEN PERFORM dg_native_bill_error('BILL_EMPTY');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_review','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=coalesce(b.id,gen_random_uuid()::text);PERFORM dg_native_dining_effect(action_id_value,'restaurant_bills',bill_value);
  IF b.id IS NULL THEN
   INSERT INTO restaurant_bills VALUES(bill_value,r.id,p.id,o.id,'B-'||substring(o.number FROM 3),1,o.content_version,amount_value,lines_value::text,'open',NULL,NULL,created,created);INSERT INTO _dg_native_bill_origins VALUES(bill_value,o.id,p.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_id_value,created);
  ELSE UPDATE restaurant_bills SET order_content_version=o.content_version,amount_minor=amount_value,snapshot=lines_value::text,version=version+1,status='open',attention_reason=NULL,updated_at=created WHERE id=bill_value;END IF;
  PERFORM dg_native_bill_refresh(action_id_value,bill_value);
  IF amount_value>0 THEN quote_value:=dg_native_bill_quote_create(action_id_value,bill_value,'payment',amount_value,'本次账单收银',NULL,meta,input);END IF;
  PERFORM dg_native_bill_event(action_id_value,bill_value,NULL,CASE WHEN amount_value=0 THEN '已核对本次有效明细，无待收金额；制作和就餐结束仍需分别核实。' ELSE '已生成原价账单审阅，明确确认仅建立收银请求。' END);
 ELSIF action_value='refund_review' THEN
  IF kind_value<>'bill' OR NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['billVersion','paymentId','amountMinor','reason','confirmed','_quoteId','_confirmationHash']);
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR length(trim(coalesce(body->>'reason',''))) NOT BETWEEN 3 AND 200 THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;IF dg_native_restaurant_integer(body->'billVersion',1,9007199254740991)<>b.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
  SELECT * INTO parent FROM restaurant_financial_operations WHERE id=body->>'paymentId' AND bill_id=b.id AND kind='payment' FOR UPDATE;amount_value:=dg_native_restaurant_integer(body->'amountMinor',1,100000000);
  IF parent.id IS NULL OR coalesce(dg_native_bill_refundable(parent.id),0)<amount_value OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=b.id AND error_code='FINANCIAL_RECONCILIATION_REQUIRED') THEN PERFORM dg_native_bill_error('REFUND_UNAVAILABLE');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_refund_review','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=b.id;quote_value:=dg_native_bill_quote_create(action_id_value,bill_value,'refund',amount_value,trim(body->>'reason'),parent.id,meta,input);PERFORM dg_native_bill_event(action_id_value,bill_value,NULL,'经理已审阅原收款及当前可退额，尚未发送退款。');
 ELSIF action_value='confirm' THEN
  IF kind_value<>'quote' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['quoteId','_confirmationHash','confirmed']);
  SELECT * INTO q FROM restaurant_financial_quotes WHERE id=target FOR UPDATE;SELECT * INTO fixed FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;
  IF body->'confirmed' IS DISTINCT FROM 'true'::jsonb OR body->>'quoteId' IS DISTINCT FROM q.id OR body->>'_confirmationHash' IS DISTINCT FROM fixed.confirmation_hash THEN PERFORM dg_native_bill_error('BILL_CONFIRMATION_INVALID');END IF;
  reason_value:=dg_native_bill_quote_reason(q.id,meta);IF reason_value IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_QUOTE_CHANGED');END IF;
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=r.id;SELECT * INTO parent FROM restaurant_financial_operations WHERE id=q.parent_payment_id;payload:=q.payload::jsonb;amount_value:=(payload->>'amountMinor')::bigint;operation_value:=gen_random_uuid()::text;bill_value:=b.id;
  action_id_value:=dg_native_dining_action(meta,'bill_confirm','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;
  payload:=jsonb_build_object('operationId',operation_value,'kind',q.kind,'restaurantId',r.id,'billId',b.id,'orderId',o.id,'merchantId',config.merchant_id,'amountMinor',amount_value,'currency','CNY','parentPaymentId',q.parent_payment_id,'parentRemoteTransactionId',parent.remote_transaction_id);
  PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_operations',operation_value);
  INSERT INTO restaurant_financial_operations(id,bill_id,kind,parent_payment_id,quote_id,status,version,amount_minor,provider_id,merchant_id,config_version,config_snapshot,request_payload,request_hash,reason,simulated,actor_id,session_id,focus_version,party_access_version,created_at,updated_at)
  VALUES(operation_value,b.id,q.kind,q.parent_payment_id,q.id,'queued',1,amount_value,config.provider_id,config.merchant_id,config.version,to_jsonb(config)::text,payload::text,dg_native_office_hash(payload),q.payload::jsonb->>'reason',1,meta->>'actorId',meta->>'sessionId',(meta->>'focusVersion')::bigint,p.access_version,created,created);
  INSERT INTO _dg_native_bill_operation_origins VALUES(operation_value,action_id_value,q.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),dg_native_office_hash(payload),created);
  PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_quotes',q.id);UPDATE restaurant_financial_quotes SET status='consumed' WHERE id=q.id;PERFORM dg_native_bill_refresh(action_id_value,b.id);PERFORM dg_native_bill_event(action_id_value,b.id,operation_value,'已明确确认并持久保存原请求；尚无可信收款或退款结果。');
 ELSE
  IF kind_value<>'operation' THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;PERFORM dg_native_restaurant_fields(body,ARRAY['version','action','confirmed']);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target FOR UPDATE;
  IF body->>'action'<>'withdraw' OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;IF operation.kind='refund' AND NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;
  IF dg_native_restaurant_integer(body->'version',1,9007199254740991)<>operation.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;IF operation.status<>'queued' OR operation.send_attempts<>0 OR operation.lease_token IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_ALREADY_SENT');END IF;
  action_id_value:=dg_native_dining_action(meta,'bill_withdraw','party',p.id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_id_value;bill_value:=b.id;PERFORM dg_native_dining_effect(action_id_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='cancelled',version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_id_value,b.id);PERFORM dg_native_bill_event(action_id_value,b.id,operation.id,'已撤回尚未发送的原请求；未生成收款、退款或远端关闭事实。');
 END IF;
 INSERT INTO _dg_native_bill_results VALUES(action_id_value,r.id,bill_value,p.access_version,created);RETURN action_id_value;
END;$dg$;
